package com.amine.chessmath;

import com.github.bhlangonijr.chesslib.Board;
import com.github.bhlangonijr.chesslib.Piece;
import com.github.bhlangonijr.chesslib.Side;
import com.github.bhlangonijr.chesslib.Square;
import com.github.bhlangonijr.chesslib.move.Move;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Standard chess adapter. Only moves generated by chesslib can enter the history. */
public final class ChessGame {
    private final Board board = new Board();
    private final List<String> moves = new ArrayList<>();

    public ChessGame() { }

    public static ChessGame fromHistory(List<String> history) {
        if (history == null) throw new IllegalArgumentException("Missing history");
        ChessGame game = new ChessGame();
        for (String move : history) game.play(move);
        return game;
    }

    public List<String> history() { return Collections.unmodifiableList(new ArrayList<>(moves)); }
    public String fen() { return board.getFen(); }
    public boolean whiteToMove() { return board.getSideToMove() == Side.WHITE; }

    public char pieceAt(int index) {
        if (index < 0 || index > 63) throw new IllegalArgumentException("Square outside board");
        Piece piece = board.getPiece(Square.squareAt((7 - index / 8) * 8 + index % 8));
        return piece == Piece.NONE ? '.' : piece.getFenSymbol().charAt(0);
    }

    public List<String> legalMoves() {
        if (!result().isEmpty()) return Collections.emptyList();
        return generatedMoves();
    }

    private List<String> generatedMoves() {
        List<String> legal = new ArrayList<>();
        for (Move move : board.legalMoves()) legal.add(move.toString());
        return Collections.unmodifiableList(legal);
    }

    public void play(String uci) {
        if (uci == null || !legalMoves().contains(uci)) throw new IllegalArgumentException("Illegal move: " + uci);
        applyGenerated(uci);
        moves.add(uci);
    }

    private void applyGenerated(String uci) {
        for (Move move : board.legalMoves()) {
            if (move.toString().equals(uci)) {
                if (!board.doMove(move)) throw new IllegalStateException("Generated move refused");
                return;
            }
        }
        throw new IllegalArgumentException("Illegal move: " + uci);
    }

    public String result() {
        // Checkmate takes precedence over the automatic 75-move draw.
        if (board.isMated()) return whiteToMove() ? "Zwart wint: schaakmat" : "Wit wint: schaakmat";
        if (board.isStaleMate()) return "Remise: pat";
        if (deadMaterial()) return "Remise: onvoldoende materiaal";
        if (board.isRepetition(5)) return "Remise: vijfmaal dezelfde stelling";
        if (board.getHalfMoveCounter() >= 150) return "Remise: 75 zetten zonder pionzet of slag";
        return "";
    }

    public boolean claimableDraw() {
        return result().isEmpty() && (board.isRepetition(3) || board.getHalfMoveCounter() >= 100);
    }

    public boolean claimableAfter(String uci) {
        if (uci == null || !legalMoves().contains(uci)) return false;
        applyGenerated(uci);
        try {
            // The intended move is not committed, including when it would end the game.
            return !board.isMated() && (board.isRepetition(3) || board.getHalfMoveCounter() >= 100);
        } finally { board.undoMove(); }
    }

    public int checkSquare() {
        if (!board.isKingAttacked()) return -1;
        int square = board.getKingSquare(board.getSideToMove()).ordinal();
        return (7 - square / 8) * 8 + square % 8;
    }

    /** Conservative verified dead-material patterns; deliberately avoids chesslib's false positives. */
    private boolean deadMaterial() {
        int knights = 0, bishops = 0, bishopColor = -1;
        boolean sameBishopColor = true;
        for (int i = 0; i < 64; i++) {
            char p = Character.toLowerCase(pieceAt(i));
            if (p == 'p' || p == 'r' || p == 'q') return false;
            if (p == 'n') knights++;
            if (p == 'b') {
                bishops++;
                int color = (i / 8 + i % 8) % 2;
                if (bishopColor != -1 && bishopColor != color) sameBishopColor = false;
                bishopColor = color;
            }
        }
        return knights + bishops <= 1 || (knights == 0 && sameBishopColor);
    }

    /** Worker-owned copy retains repetition and counters, including speculative branch history. */
    ChessGame copy() {
        ChessGame copy = new ChessGame();
        copy.board.loadFromFen(board.getFen());
        copy.board.getHistory().clear();
        copy.board.getHistory().addAll(board.getHistory());
        copy.moves.addAll(moves);
        return copy;
    }
}
